// The shape of @solidjs/router 2.0.0-next.41 createRouter (dist/routers/factory.jsx:219-329): a component declared in the body,
// returned as Object.assign(RouterComponent, { ... }). This one calls its children function in its own body.
export function createRouter(config) {
  function RouterComponent(props) {
    return props.children({ path: config.base });
  }
  const instance = Object.assign(RouterComponent, { config });
  return instance;
}
